:root {
  --gray-900: #111827;
  --white: #ffffff;
}

[data-theme="light"] {
  --bg-page: var(--white);
  --text-primary: var(--gray-900);
}

/* Question: How should the Dark Theme be defined? */

.alert-box {
  /* Component Tokens */
  --alert-bg: var(--bg-surface);
  background: var(--alert-bg);
}

/* Requirement: A 'danger' variant that has a red background */

:root {
  --gray-100: #f3f4f6;
  --gray-900: #111827;
}

[data-theme="light"] {
  --bg-surface: var(--gray-100);
}

[data-theme="dark"] {
  --bg-surface: var(--gray-900);
}

/* Component Code */
.card {
  background-color: var(--gray-100);
  color: var(--gray-900);
  padding: 1rem;
}
